class AssetDataManager {
    constructor() {
        this.storageKey = "NEW_OUTLET_DONE_TRANSFER_V19";
        this.assets = this.loadLocalAssets();
    }

    loadLocalAssets() {
        ["NEW_OUTLET_ASSETS_OUTLET_SPECIFIC_V5", "NEW_OUTLET_ASSETS_3ROLE_VALIDATION_V6", "NEW_OUTLET_ASSETS_FIXED_V7", "NEW_OUTLET_ASSETS_CLEAN_V8", "NEW_OUTLET_SYSTEM_PROPER_V9", "NEW_OUTLET_RECEIVER_V10", "NEW_OUTLET_RAB_SEPARATED_V11", "NEW_OUTLET_JABO_COL_E_V12", "NEW_OUTLET_TGL_PENGAJUAN_V13", "NEW_OUTLET_FORMATTED_DATE_V14", "NEW_OUTLET_CONTINUOUS_SYNC_V15", "NEW_OUTLET_XYZ_CHECKBOX_V16", "NEW_OUTLET_XYZ_PRECISE_V17", "NEW_OUTLET_PROPER_V18"].forEach(k => {
            try { localStorage.removeItem(k); } catch (e) {}
        });

        const saved = localStorage.getItem(this.storageKey);
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                if (Array.isArray(parsed) && parsed.length > 0) {
                    return parsed;
                }
            } catch (e) {
                console.error("Failed to parse saved assets", e);
            }
        }
        return JSON.parse(JSON.stringify(INITIAL_ASSETS));
    }

    saveAssets() {
        localStorage.setItem(this.storageKey, JSON.stringify(this.assets));
        try {
            window.dispatchEvent(new Event('assetsUpdated'));
        } catch(e) {}
    }

    resetToDefault() {
        this.assets = JSON.parse(JSON.stringify(INITIAL_ASSETS));
        this.saveAssets();
        return this.assets;
    }

    getAssets(areaFilter = null) {
        if (!areaFilter || areaFilter === 'ALL') return this.assets;
        return this.assets.filter(a => a.area === areaFilter);
    }

    getOutlets(areaFilter = null) {
        const assets = this.getAssets(areaFilter);
        const outletMap = {};

        assets.forEach(a => {
            if (!a.outlet) return;
            const uniqueKey = a.outlet + " (RAB: " + a.rabCode + ")";
            
            if (!outletMap[uniqueKey]) {
                outletMap[uniqueKey] = {
                    key: uniqueKey,
                    name: a.outlet,
                    rabCode: a.rabCode,
                    area: a.area,
                    areaLabel: a.areaLabel,
                    tglPengajuan: a.tglPengajuan || '13/7/2026',
                    tglOrder: a.tglPengajuan || '13/7/2026',
                    tglOpening: a.tglOpening || '17/08/2026',
                    items: []
                };
            }
            outletMap[uniqueKey].items.push(a);
        });

        return Object.values(outletMap).map(o => {
            const total = o.items.length;
            const acceptedCount = o.items.filter(i => parseInt(i.stage) === 5 || i.validationStatus === 'ACCEPTED' || i.terimaOutlet || i.ceklisZ).length;
            const percentage = total > 0 ? Math.round((acceptedCount / total) * 100) : 0;
            
            const rejectedCount = o.items.filter(i => i.validationStatus === 'REJECTED').length;
            const pendingOutletCount = o.items.filter(i => parseInt(i.stage) === 4 || i.validationStatus === 'IN_TRANSIT').length;
            const discrepancies = o.items.filter(i => (i.validationStatus === 'ACCEPTED' || i.terimaOutlet || i.ceklisZ) && i.qtyDiterima < i.qty).length;
            
            let slaText = "⏱️ Estimasi 14 Hari";
            let slaClass = "sla-normal";
            if (percentage === 100) {
                slaText = "✅ Selesai (100%)";
                slaClass = "sla-success";
            } else if (rejectedCount > 0) {
                slaText = "❌ " + rejectedCount + " Item Ditolak Outlet";
                slaClass = "sla-alert";
            } else if (discrepancies > 0) {
                slaText = "⚠️ " + discrepancies + " Item Selisih Qty";
                slaClass = "sla-alert";
            } else if (percentage < 30) {
                slaText = "⚠️ Sisa 2 Hari";
                slaClass = "sla-urgent";
            }

            return {
                ...o,
                total,
                acceptedCount,
                rejectedCount,
                pendingOutletCount,
                percentage,
                discrepancies,
                slaText,
                slaClass
            };
        }).sort((a, b) => a.key.localeCompare(b.key));
    }

    getOutletDetails(outletKey) {
        const outlets = this.getOutlets();
        return outlets.find(o => o.key === outletKey || o.name === outletKey);
    }

    batchUpdateLogistics(outletKey, itemsUpdates) {
        itemsUpdates.forEach(upd => {
            const asset = this.assets.find(a => a.id === upd.id);
            if (asset) {
                asset.qtyDiterima = parseInt(upd.qtyDiterima) || 0;
                asset.keterangan = upd.keterangan || '';
                if (upd.picPenerima !== undefined) {
                    asset.picPenerima = upd.picPenerima || '';
                }

                if (upd.ceklisX !== undefined) asset.ceklisX = Boolean(upd.ceklisX);
                if (upd.ceklisY !== undefined) asset.ceklisY = Boolean(upd.ceklisY);
                if (upd.ceklisZ !== undefined) asset.ceklisZ = Boolean(upd.ceklisZ);

                const st = upd.statusPengiriman || '';

                if (st.includes('Done Transfer') || st.includes('Transfer')) {
                    asset.validationStatus = 'PENDING_LOGISTIK';
                    asset.statusPengiriman = '💸 Done Transfer (Perpindahan aset melalui sistem)';
                    asset.stage = 3;
                    asset.ceklisX = true;
                    asset.ceklisY = false;
                    asset.ceklisZ = false;
                } else if (st.includes('Ready Gudang') || st.includes('Dalam Pengiriman') || st.includes('Ready Antar') || st.includes('Stage 2') || st.includes('Stage 4')) {
                    asset.ceklisX = true;
                    asset.ceklisY = true;
                    if (st.includes('Dalam Pengiriman')) {
                        asset.validationStatus = 'IN_TRANSIT';
                        asset.statusPengiriman = '🚚 Dalam Pengiriman (Konfirmasi Outlet)';
                        asset.stage = 4;
                    } else {
                        asset.validationStatus = 'PENDING_LOGISTIK';
                        asset.statusPengiriman = '📦 Ready Gudang / Ready Antar';
                        asset.stage = 2;
                    }
                } else if (st.includes('Valid & Diterima') || st.includes('Stage 5')) {
                    asset.ceklisX = true;
                    asset.ceklisY = true;
                    asset.ceklisZ = true;
                    asset.validationStatus = 'ACCEPTED';
                    asset.statusPengiriman = '✅ Valid & Diterima Outlet';
                    asset.stage = 5;
                } else if (st.includes('Procurement')) {
                    asset.validationStatus = 'PENDING_LOGISTIK';
                    asset.statusPengiriman = '🛒 Procurement PO';
                    asset.stage = 3;
                    asset.ceklisX = true;
                    asset.ceklisY = false;
                    asset.ceklisZ = false;
                } else {
                    asset.validationStatus = 'PENDING_LOGISTIK';
                    asset.statusPengiriman = '📝 Pengajuan RAB';
                    asset.stage = 1;
                    asset.ceklisX = false;
                    asset.ceklisY = false;
                    asset.ceklisZ = false;
                }
            }
        });

        this.saveAssets();
        return this.getOutletDetails(outletKey);
    }

    outletAcceptItem(assetId, picName) {
        const asset = this.assets.find(a => a.id === assetId);
        if (!asset) return null;

        asset.ceklisX = true;
        asset.ceklisY = true;
        asset.ceklisZ = true;
        asset.validationStatus = 'ACCEPTED';
        asset.statusPengiriman = '✅ Valid & Diterima Outlet';
        asset.terimaOutlet = true;
        asset.pengirimanAset = true;
        asset.picPenerima = picName || asset.picPenerima || 'PIC Outlet';
        asset.tglTerima = new Date().toISOString().split('T')[0];
        asset.stage = 5;
        asset.alasanPenolakan = '';

        this.saveAssets();
        return asset;
    }

    outletRejectItem(assetId, picName, reason) {
        const asset = this.assets.find(a => a.id === assetId);
        if (!asset) return null;

        asset.ceklisZ = false;
        asset.validationStatus = 'REJECTED';
        asset.statusPengiriman = '❌ DITOLAK OUTLET (Perlu Revisi Logistik)';
        asset.terimaOutlet = false;
        asset.pengirimanAset = false;
        asset.stage = 3;
        asset.picPenerima = picName || asset.picPenerima || 'PIC Outlet';
        asset.alasanPenolakan = reason || 'Fisik tidak sesuai dengan yang diketik Logistik';
        asset.tglTerima = new Date().toISOString().split('T')[0];

        this.saveAssets();
        return asset;
    }
}

window.dataManager = new AssetDataManager();
